{"packet_id":"D041-01","doc_id":"D041","jurisdiction":"Los Angeles, CA","category":"rent_increase_limits","lifecycle":"enacted","title":"Los Angeles RSO allowable rent increase","requirement":"Rent may be increased only once every 12 months by the allowable percentage set by LAHD; effective February 2, 2026 landlords may no longer add a utility percentage increase or a 10% increase for an additional dependent.","key_value":"Once every 12 months at the LAHD allowable increase percentage","coverage_conditions":"Rental properties in the City of Los Angeles first built on or before October 1, 1978, including apartments, condominiums, townhomes, duplexes, ADUs, JADUs and mobile homes, plus replacement units.","applicability":{"conditions":[{"type":"built","role":"covered","op":"on_or_before","date":"1978-10-01","basis":"construction"}],"per_tenancy":"Condominium and townhome rent amounts are not regulated for tenancies that commenced after December 31, 1995.","coverage_quotes":["Generally, the RSO applies to rental properties that were first built on or before October 1, 1978, as well as replacement units under LAMC Section 151.28","Condominium (Rent amount is not regulated for tenancies that commenced after December 31, 1995)"]},"exemptions":"Condominium and townhome rent amounts are not regulated for tenancies commencing after December 31, 1995; a landlord may apply for the luxury exemption.","penalty":null,"effective_date":null,"valid_through":null,"citation":"Los Angeles Rent Stabilization Ordinance (L.A.M.C. §151.00 et seq.)","quoted_span":"Rent may be increased once every 12 months by the allowable rent increase percentage (click here to view the allowable rent increase PDF). Effective February 2, 2026, the landlord can no longer include an additional percentage increase for utilities.","interaction":null,"relations":[],"confidence":0.75,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D041-01","doc_id":"D041","jurisdiction":"Los Angeles, CA","category":"just_cause_eviction","lifecycle":"enacted","title":"Los Angeles RSO legal reasons for eviction and relocation","requirement":"A landlord may terminate an RSO tenancy only for listed at-fault causes (nonpayment, nuisance, lease violation, illegal use) or no-fault causes (owner move-in, demolition, government order); no-fault evictions require relocation assistance and termination notices must be filed with LAHD within 3 business days of service.","key_value":null,"coverage_conditions":"Rental units in the City of Los Angeles subject to the Rent Stabilization Ordinance (first built on or before October 1, 1978).","applicability":{"conditions":[{"type":"built","role":"covered","op":"on_or_before","date":"1978-10-01","basis":"construction"}],"per_tenancy":"Condominium and townhome rent amounts are not regulated for tenancies that commenced after December 31, 1995.","coverage_quotes":["Generally, the RSO applies to rental properties that were first built on or before October 1, 1978, as well as replacement units under LAMC Section 151.28","No-fault evictions require the payment of relocation assistance."]},"exemptions":null,"penalty":null,"effective_date":null,"valid_through":null,"citation":"Los Angeles Municipal Code § 151.09","quoted_span":"Legal Reasons for Eviction
Tenant is at-fault
Failure to pay rent
Failure to fix or address a violation of the rental agreement

Creating a nuisance or causing damage to the rental unit
Using the rental unit for an illegal purpose","interaction":null,"relations":[],"confidence":0.7,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D041-01","n_rules":2,"note":null}

